			for _, d in pairs(deps) do
				assert(typeof(d) == 'table', 'Dependency should be a table.')
				assert(d[1] ~= nil, 'Dependency is missing element.')
				assert(d[2] ~= nil, 'Dependency is missing expected value.')
			end
			DepGroupbox.Dependencies = deps
			DepGroupbox:Update()
		end

