	local function removeLegacyShaderPresetEffects()
		for _, name in ipairs({
			"YSLMethodShaderColor",
			"YSLMethodShaderBloom",
			"YSLMethodShaderSunRays",
		}) do
			local effect = Lighting:FindFirstChild(name)
			if effect then
				effect:Destroy()
			end
		end
	end
	removeLegacyShaderPresetEffects()

