	local playerEspRenderConnection
	local playerEspLastUpdate = 0
	local clearPlayerEspRecords

	local function clearOrphanedPlayerEsp(playerGui)
		for _, descendant in ipairs(playerGui:GetDescendants()) do
			if descendant:IsA("BillboardGui")
				and (string.sub(descendant.Name, 1, #"YSLPlayerESP") == "YSLPlayerESP"
					or string.sub(descendant.Name, 1, #"PlayerESP_") == "PlayerESP_"
					or string.sub(descendant.Name, 1, #"PlayerESPTags_") == "PlayerESPTags_"
					or string.sub(descendant.Name, 1, #"PlayerESPBottomTags_") == "PlayerESPBottomTags_") then
				descendant:Destroy()
			end
		end
	end
	local initialPlayerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
	if initialPlayerGui then
		clearOrphanedPlayerEsp(initialPlayerGui)
	end

	local function ensurePlayerEspGui()
		local playerGui = LocalPlayer:FindFirstChildOfClass("PlayerGui")
		if not playerGui then
			return false
		end
		if playerEspGui == playerGui then
			return true
		end
		if clearPlayerEspRecords then
			clearPlayerEspRecords()
		end
		clearOrphanedPlayerEsp(playerGui)
		playerEspGui = playerGui
		return true
	end

	-- Adapted from uni's project-rain-oss player_esp.lua with permission.
	local function createBar(parent, name, backgroundColor, size, position, rotation)
		local bar = Instance.new("Frame")
		bar.Name = name
		bar.AnchorPoint = Vector2.new(0.5, 0.5)
		bar.BackgroundColor3 = Color3.fromRGB(8, 12, 14)
		bar.BackgroundTransparency = 0.08
		bar.BorderSizePixel = 0
		bar.Position = position
		bar.Rotation = 0
		bar.Size = size
		bar.Parent = parent

		local stroke = Instance.new("UIStroke")
		stroke.Color = Color3.new(0, 0, 0)
		stroke.Transparency = 0.08
		stroke.Thickness = 1.5
		stroke.Parent = bar

		local fill = Instance.new("Frame")
		fill.Name = "FillBar"
		fill.BorderSizePixel = 0
		fill.BackgroundColor3 = backgroundColor
		fill.AnchorPoint = Vector2.new(0, 1)
		fill.Position = UDim2.fromScale(0, 1)
		fill.Size = UDim2.fromScale(1, 1)
		fill.Parent = bar

		local gradient = Instance.new("UIGradient")
		gradient.Color = ColorSequence.new({
			ColorSequenceKeypoint.new(0, Color3.new(1, 1, 1)),
			ColorSequenceKeypoint.new(1, Color3.fromRGB(175, 175, 175)),
		})
		gradient.Rotation = rotation == 180 and -90 or -180
		gradient.Parent = fill

		return bar, fill
	end

