	local function destroyPlayerEspRecord(player)
		local record = playerEspRecords[player]
		if not record then
			return
		end
		record.Billboard:Destroy()
		record.NameBillboard:Destroy()
		record.BottomBillboard:Destroy()
		playerEspRecords[player] = nil
	end

	clearPlayerEspRecords = function()
		for player in pairs(playerEspRecords) do
			destroyPlayerEspRecord(player)
		end
		table.clear(playerEspRecords)
		if playerEspGui then
			clearOrphanedPlayerEsp(playerEspGui)
		end
	end

	local function getPlayerNameTags(player, humanoid, root, camera)
		local text = {}
		local tags = playerEspSettings.Tags
		if tags["Roblox Display Name"] then
			table.insert(text, player.DisplayName)
		end
		if tags["Roblox Player Name"] then
			table.insert(text, player.Name)
		end
		if tags["Health %"] then
			table.insert(text, string.format(
				"(%d%%)",
				math.floor(math.clamp(humanoid.Health / math.max(humanoid.MaxHealth, 1), 0, 1) * 100)
			))
		end
		if tags["HP/Max"] then
			table.insert(text, string.format(
				"(%d/%dhp)",
				math.floor(humanoid.Health + 0.5),
				math.floor(math.max(humanoid.MaxHealth, 1) + 0.5)
			))
		end
		if tags.Distance then
			local distance = (camera.CFrame.Position - root.Position).Magnitude
			local formattedDistance = playerEspSettings.DistanceInStuds
					and string.format("%ds", math.floor(distance + 0.5))
				or (distance > 1000 and string.format("%.1fkm", distance / 1000)
					or string.format("%dm", math.floor(distance + 0.5)))
			table.insert(text, string.format("[%s]", formattedDistance))
		end
		return table.concat(text, " ")
	end

	local function getPlayerBottomTags(character)
		local text = {}
		local tags = playerEspSettings.Tags
		if tags.Ping then
			local ping = character:GetAttribute("AveragePing")
			if type(ping) == "number" then
				table.insert(text, ping > 1000
					and string.format("[%ds]", math.floor(ping / 1000 + 0.5))
					or string.format("[%dms]", math.floor(ping + 0.5)))
			end
		end
		if tags.Agility then
			local agility = character:FindFirstChild("PassiveAgility")
			if agility and (agility:IsA("NumberValue") or agility:IsA("IntValue")) and agility.Value > 0 then
				table.insert(text, string.format("[%i agil]", agility.Value))
			end
		end
		return table.concat(text, " ")
	end

	local function applyEspFade(record, distance, mousePosition, camera)
		local transparency = 0.2
		if playerEspSettings.Fadeout and distance > playerEspSettings.FadeoutDistance then
			local fadeDistance = math.max(playerEspSettings.FadeoutDistance, 1)
			local fade = math.min(1, (distance - fadeDistance) / fadeDistance) * 0.8
			if playerEspSettings.FadeoutHover then
				local screenPosition, onScreen = camera:WorldToViewportPoint(record.Root.Position)
				if onScreen then
					local dx = screenPosition.X - mousePosition.X
					local dy = screenPosition.Y - mousePosition.Y
					fade *= math.min(1, (dx * dx + dy * dy) / 10000)
				end
			end
			transparency = math.clamp(0.2 + fade, 0.2, 1)
		end
		record.NameLabel.TextTransparency = transparency
		record.NameStroke.Transparency = transparency
		record.BottomLabel.TextTransparency = transparency
		record.BottomStroke.Transparency = transparency
	end

	local function getThemeGradientColor(position)
		if not gradientEnabled then
			return library.AccentColor
		end
		local dark = library.AccentColorDark or library:GetDarkerColor(library.AccentColor)
		position = position % 1
		local section = position * 4
		local index = math.floor(section)
		local blend = section - index
		blend = blend * blend * (3 - 2 * blend)
		if index == 0 then
			return library.AccentColor:Lerp(library.FontColor, blend)
		elseif index == 1 then
			return library.FontColor:Lerp(dark, blend)
		elseif index == 2 then
			return dark:Lerp(library.FontColor, blend)
		end
		return library.FontColor:Lerp(library.AccentColor, blend)
	end

	local function updatePlayerEspFrame()
		if not playerEspSettings.Enabled or not ensurePlayerEspGui() then
			return
		end
		local now = os.clock()
		if now - playerEspLastUpdate < 1 / math.clamp(playerEspSettings.UpdateRate, 1, 60) then
			return
		end
		playerEspLastUpdate = now
		local camera = workspace.CurrentCamera
		if not camera then
			return
		end

		local mousePosition = UserInputService:GetMouseLocation()
		local seen = {}
		for _, player in ipairs(Players:GetPlayers()) do
			if player ~= LocalPlayer then
				local character = player.Character
				local humanoid = character and character:FindFirstChildOfClass("Humanoid")
				local root = character and character:FindFirstChild("HumanoidRootPart")
				if humanoid and root and root:IsA("BasePart") and humanoid.Health > 0 then
					local record = playerEspRecords[player]
					if not record or record.Root ~= root then
						destroyPlayerEspRecord(player)
						record = createPlayerEspRecord(player, root)
						playerEspRecords[player] = record
					end
					seen[player] = true
					local distance = (camera.CFrame.Position - root.Position).Magnitude
					local visible = distance <= playerEspSettings.MaxDistance
					record.Billboard.Enabled = visible
					record.NameBillboard.Enabled = visible and playerEspSettings.Names
					record.BottomBillboard.Enabled = visible and playerEspSettings.Names
					record.Box.Visible = visible and playerEspSettings.Boxes
					record.BoxOutline.Visible = visible and playerEspSettings.Boxes
					record.BoxStroke.Color = getThemeGradientColor(now / gradientDuration)
					record.Box.BackgroundColor3 = library.AccentColor
					if now - record.BoundsUpdatedAt >= 0.5 then
						record.BoundsUpdatedAt = now
						local boundsSuccess, boundsFrame, boundsSize = pcall(character.GetBoundingBox, character)
						if boundsSuccess then
							record.Billboard.Size = UDim2.new(
								math.max(boundsSize.X + 0.8, 2),
								0,
								math.max(boundsSize.Y + 0.4, 3),
								0
							)
							local boundsOffsetY = boundsFrame.Position.Y - root.Position.Y
							record.Billboard.StudsOffset = Vector3.new(0, boundsOffsetY, 0)
							record.NameBillboard.StudsOffset = Vector3.new(
								0,
								boundsOffsetY + boundsSize.Y * 0.5 + 2.25,
								0
							)
							record.BottomBillboard.StudsOffset = Vector3.new(
								0,
								boundsOffsetY + boundsSize.Y * 0.5 + 0.9,
								0
							)
						end
					end
					record.HealthBar.Visible = visible and playerEspSettings.Healthbar
					record.NameLabel.FontFace = library.Font
					record.NameLabel.TextSize = playerEspSettings.TextSize
					record.NameLabel.TextColor3 = playerEspSettings.NameColor
					record.NameStroke.Color = playerEspSettings.NameOutlineColor
					record.BottomLabel.FontFace = library.Font
					record.BottomLabel.TextSize = playerEspSettings.TextSize
					record.BottomLabel.TextColor3 = playerEspSettings.NameColor
					record.BottomStroke.Color = playerEspSettings.NameOutlineColor
					applyEspFade(record, distance, mousePosition, camera)
					record.NameLabel.Text = getPlayerNameTags(player, humanoid, root, camera)
					record.NameBillboard.Enabled = visible and playerEspSettings.Names
						and record.NameLabel.Text ~= ""
					record.BottomLabel.Text = getPlayerBottomTags(character)
					record.BottomBillboard.Enabled = visible and playerEspSettings.Names
						and record.BottomLabel.Text ~= ""
					local healthRatio = math.clamp(humanoid.Health / math.max(humanoid.MaxHealth, 1), 0, 1)
					record.HealthFill.Size = UDim2.new(1, 0, healthRatio, 0)
					local healthColor = Color3.fromHSV(healthRatio * 0.33, 0.82, 1)
					record.HealthFill.BackgroundColor3 = healthColor
					local healthGradient = record.HealthFill:FindFirstChildOfClass("UIGradient")
					if healthGradient then
						healthGradient.Color = ColorSequence.new(
							healthColor:Lerp(Color3.new(1, 1, 1), 0.2),
							healthColor
						)
					end
					for _, divider in ipairs(record.Dividers) do
						divider.Visible = healthRatio > 0 and tonumber(divider.Name) < healthRatio
					end
				end
			end
		end
		for player in pairs(playerEspRecords) do
			if not seen[player] then
				destroyPlayerEspRecord(player)
			end
		end
	end

	local function refreshPlayerEsp()
		if not playerEspSettings.Enabled then
			if playerEspRenderConnection then
				playerEspRenderConnection:Disconnect()
				playerEspRenderConnection = nil
			end
			clearPlayerEspRecords()
			playerEspGui = nil
			return
		end
		if not ensurePlayerEspGui() then
			warn("[YSL Method] Player ESP could not start because PlayerGui is unavailable")
			return
		end
		if not playerEspRenderConnection then
			playerEspRenderConnection = RunService.RenderStepped:Connect(updatePlayerEspFrame)
		end
	end

	function playerEsp:SetEnabled(enabled)
		playerEspSettings.Enabled = not not enabled
		refreshPlayerEsp()
	end

