	function playerEsp:GetPreviewSettings()
		local snapshot = {}
		for key, value in pairs(playerEspSettings) do
			snapshot[key] = key == "Tags" and table.clone(value) or value
		end
		snapshot.BoxColor = getThemeGradientColor(os.clock() / gradientDuration)
		return snapshot
	end

	library:OnUnload(function()
		if playerEspRenderConnection then
			playerEspRenderConnection:Disconnect()
			playerEspRenderConnection = nil
		end
		clearPlayerEspRecords()
		playerEspGui = nil
	end)
	visuals.PlayerESP = playerEsp

	local function setFogEnabled(enabled)
		if enabled then
			if not visualAtmosphere or not visualAtmosphere.Parent then
				visualAtmosphere = Instance.new("Atmosphere")
				visualAtmosphere.Name = "YSLMethodAtmosphere"
				visualAtmosphere.Parent = Lighting
			end
			visualAtmosphere.Density = fogDensity
			visualAtmosphere.Offset = fogOffset
			visualAtmosphere.Color = fogColor
			visualAtmosphere.Decay = fogDecay
			visualAtmosphere.Glare = fogGlare
			visualAtmosphere.Haze = fogHaze
		else
			if visualAtmosphere then
				visualAtmosphere:Destroy()
				visualAtmosphere = nil
			end
		end
	end

	local function updateFog()
		if not visualAtmosphere or not visualAtmosphere.Parent then
			return
		end
		visualAtmosphere.Density = fogDensity
		visualAtmosphere.Offset = fogOffset
		visualAtmosphere.Color = fogColor
		visualAtmosphere.Decay = fogDecay
		visualAtmosphere.Glare = fogGlare
		visualAtmosphere.Haze = fogHaze
	end

	function visuals:SetFogEnabled(enabled)
		setFogEnabled(enabled)
	end

	function visuals:SetFogDensity(value)
		fogDensity = math.clamp(tonumber(value) or fogDensity, 0, 1)
		updateFog()
	end

	function visuals:SetFogOffset(value)
		fogOffset = math.clamp(tonumber(value) or fogOffset, -1, 1)
		updateFog()
	end

	function visuals:SetFogHaze(value)
		fogHaze = math.clamp(tonumber(value) or fogHaze, 0, 10)
		updateFog()
	end

	function visuals:SetFogGlare(value)
		fogGlare = math.clamp(tonumber(value) or fogGlare, 0, 10)
		updateFog()
	end

	function visuals:SetFogColor(value)
		if typeof(value) == "Color3" then
			fogColor = value
			updateFog()
		end
	end

	function visuals:SetFogDecay(value)
		if typeof(value) == "Color3" then
			fogDecay = value
			updateFog()
		end
	end

	function visuals:SetHueEnabled(enabled)
		if enabled then
			if not hueCorrection or not hueCorrection.Parent then
				hueCorrection = Instance.new("ColorCorrectionEffect")
				hueCorrection.Name = "YSLMethodHue"
				hueCorrection.Parent = Lighting
			end
			hueCorrection.TintColor = hueColor
			hueCorrection.Saturation = 0.08
		elseif hueCorrection then
			hueCorrection:Destroy()
			hueCorrection = nil
		end
	end

	function visuals:SetHueColor(value)
		if typeof(value) == "Color3" then
			hueColor = value
			if hueCorrection and hueCorrection.Parent then
				hueCorrection.TintColor = hueColor
			end
		end
	end

	function visuals:SetSkyStyle(style)
		local styles = {
			Classic = {
				SkyboxBk = "rbxasset://textures/sky/sky512_bk.tex",
				SkyboxDn = "rbxasset://textures/sky/sky512_dn.tex",
				SkyboxFt = "rbxasset://textures/sky/sky512_ft.tex",
				SkyboxLf = "rbxasset://textures/sky/sky512_lf.tex",
				SkyboxRt = "rbxasset://textures/sky/sky512_rt.tex",
				SkyboxUp = "rbxasset://textures/sky/sky512_up.tex",
				Stars = 3000,
				CelestialBodies = true,
			},
			Sunset = {
				SkyboxBk = "rbxassetid://600830446",
				SkyboxDn = "rbxassetid://600831635",
				SkyboxFt = "rbxassetid://600832720",
				SkyboxLf = "rbxassetid://600886090",
				SkyboxRt = "rbxassetid://600833862",
				SkyboxUp = "rbxassetid://600835177",
				Stars = 500,
				CelestialBodies = true,
			},
			Arctic = {
				SkyboxBk = "rbxassetid://225469390",
				SkyboxDn = "rbxassetid://225469395",
				SkyboxFt = "rbxassetid://225469403",
				SkyboxLf = "rbxassetid://225469450",
				SkyboxRt = "rbxassetid://225469471",
				SkyboxUp = "rbxassetid://225469481",
				Stars = 4500,
				CelestialBodies = true,
			},
			Emerald = {
				SkyboxBk = "rbxassetid://271042516",
				SkyboxDn = "rbxassetid://271077243",
				SkyboxFt = "rbxassetid://271042556",
				SkyboxLf = "rbxassetid://271042310",
				SkyboxRt = "rbxassetid://271042467",
				SkyboxUp = "rbxassetid://271077958",
				Stars = 2400,
				CelestialBodies = false,
			},
			Void = {
				SkyboxBk = "rbxassetid://159248188",
				SkyboxDn = "rbxassetid://159248183",
				SkyboxFt = "rbxassetid://159248187",
				SkyboxLf = "rbxassetid://159248173",
				SkyboxRt = "rbxassetid://159248192",
				SkyboxUp = "rbxassetid://159248176",
				Stars = 8000,
				CelestialBodies = false,
			},
		}
		local preset = styles[style]
		if not preset then
			return false
		end
		skyStyle = style
		if not animatedSkyEnabled or not customSky then
			return true
		end

		customSky.SkyboxBk = preset.SkyboxBk
		customSky.SkyboxDn = preset.SkyboxDn
		customSky.SkyboxFt = preset.SkyboxFt
		customSky.SkyboxLf = preset.SkyboxLf
		customSky.SkyboxRt = preset.SkyboxRt
		customSky.SkyboxUp = preset.SkyboxUp

		customSky.StarCount = preset.Stars
		customSky.CelestialBodiesShown = preset.CelestialBodies
		return true
	end

	local function setAnimatedSky(enabled)
		animatedSkyEnabled = not not enabled
		if animatedSkyEnabled then
			if customSky and customSky.Parent then
				visuals:SetSkyStyle(skyStyle)
				return
			end
			table.clear(pausedSkies)
			for _, child in ipairs(Lighting:GetChildren()) do
				if child:IsA("Sky") then
					table.insert(pausedSkies, { Sky = child, Parent = child.Parent })
					child.Parent = nil
				end
			end

			customSky = Instance.new("Sky")
			customSky.Name = "YSLMethodAnimatedSky"
			customSky.SkyboxBk = "rbxasset://textures/sky/sky512_bk.tex"
			customSky.SkyboxDn = "rbxasset://textures/sky/sky512_dn.tex"
			customSky.SkyboxFt = "rbxasset://textures/sky/sky512_ft.tex"
			customSky.SkyboxLf = "rbxasset://textures/sky/sky512_lf.tex"
			customSky.SkyboxRt = "rbxasset://textures/sky/sky512_rt.tex"
			customSky.SkyboxUp = "rbxasset://textures/sky/sky512_up.tex"
			customSky.Parent = Lighting
			visuals:SetSkyStyle(skyStyle)
		else
			if customSky then
				customSky:Destroy()
				customSky = nil
			end
			for _, entry in ipairs(pausedSkies) do
				if entry.Sky.Parent == nil and entry.Parent then
					entry.Sky.Parent = entry.Parent
				end
			end
			table.clear(pausedSkies)
		end
	end

	function visuals:SetGradient(enabled, duration)
		gradientEnabled = not not enabled
		gradientDuration = math.clamp(tonumber(duration) or gradientDuration, 1, 12)
	end

	function visuals:SetClockTime(value)
		clockTime = math.clamp(tonumber(value) or clockTime, 0, 24)
		if customTimeEnabled then
			Lighting.ClockTime = clockTime % 24
		end
	end

	function visuals:SetClockTimeEnabled(enabled)
		enabled = not not enabled
		if enabled == customTimeEnabled then
			return
		end
		customTimeEnabled = enabled
		if customTimeEnabled then
			previousClockTime = Lighting.ClockTime
			Lighting.ClockTime = clockTime % 24
		elseif previousClockTime ~= nil then
			Lighting.ClockTime = previousClockTime
			previousClockTime = nil
		end
	end

	function visuals:SetAnimatedSky(enabled)
		setAnimatedSky(enabled)
	end

	library:GiveSignal(RunService.RenderStepped:Connect(function(deltaTime)
		if not animatedSkyEnabled then
			return
		end
		animationClock += deltaTime
		if customSky and customSky.Parent then
			customSky.SkyboxOrientation = Vector3.new(0, (animationClock * 1.5) % 360, 0)
		end
	end))
	local function cleanup()
		removeLegacyShaderPresetEffects()
		setFogEnabled(false)
		visuals:SetHueEnabled(false)
		if customTimeEnabled and previousClockTime ~= nil then
			Lighting.ClockTime = previousClockTime
			previousClockTime = nil
		end
		setAnimatedSky(false)
	end
	library.ScreenGui.Destroying:Connect(cleanup)
	library:OnUnload(cleanup)

	return visuals
end
	end,
	["@src/ui/arraylist"] = function()
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

return function(library)
	local gradientEnabled = true
	local gradientDuration = 5
	local visible = false
	local backgroundEnabled = true
	local textSize = 14
	local lastColorRefresh = 0
	local labels = {}
	local leftSide = false
	local bottomSide = false
	local dragging = false
	local refresh

	local panel = library:Create("Frame", {
		Name = "YSLArrayList",
		Active = true,
		AnchorPoint = Vector2.new(1, 0),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.new(1, -8, 0, 88),
		Size = UDim2.fromOffset(240, 20),
		Visible = false,
		ZIndex = 80,
		Parent = library.ScreenGui,
	})
	library.ArrayListFrame = panel
	library:MakeDraggable(panel, 16, true)
	panel.InputBegan:Connect(function(input)
		if input.UserInputType == Enum.UserInputType.MouseButton1 then
			dragging = true
		end
	end)

	local function updatePlacement()
		local absolutePosition = panel.AbsolutePosition
		local absoluteSize = panel.AbsoluteSize
		local center = absolutePosition + absoluteSize * 0.5
		local camera = workspace.CurrentCamera
		local viewport = camera and camera.ViewportSize
		if not viewport then
			return
		end

		local newLeftSide = center.X < viewport.X * 0.5
		local newBottomSide = center.Y > viewport.Y * 0.5
		local changed = newLeftSide ~= leftSide or newBottomSide ~= bottomSide
		leftSide = newLeftSide
		bottomSide = newBottomSide
		panel.AnchorPoint = Vector2.new(leftSide and 0 or 1, bottomSide and 1 or 0)
		library.ArrayListAnchorPoint = panel.AnchorPoint
		panel.Position = UDim2.fromOffset(
			leftSide and absolutePosition.X or absolutePosition.X + absoluteSize.X,
			bottomSide and absolutePosition.Y + absoluteSize.Y or absolutePosition.Y
		)
		if changed then
			refresh()
		end
	end

	library:GiveSignal(UserInputService.InputEnded:Connect(function(input)
		if dragging and input.UserInputType == Enum.UserInputType.MouseButton1 then
			dragging = false
			updatePlacement()
		end
	end))

	local list = library:Create("Frame", {
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(0, 16),
		Size = UDim2.new(1, 0, 1, -16),
		ZIndex = 80,
		Parent = panel,
	})
	local layout = library:Create("UIListLayout", {
		Padding = UDim.new(0, 0),
		SortOrder = Enum.SortOrder.LayoutOrder,
		VerticalAlignment = Enum.VerticalAlignment.Top,
		Parent = list,
	})

	local function getGradientColor(position)
		local dark = library.AccentColorDark or library:GetDarkerColor(library.AccentColor)
		position = position % 1
		local section = position * 4
		local index = math.floor(section)
		local blend = section - index
		blend = blend * blend * (3 - 2 * blend)
		if index == 0 then
			return library.AccentColor:Lerp(library.FontColor, blend)
		elseif index == 1 then
			return library.FontColor:Lerp(dark, blend)
		elseif index == 2 then
			return dark:Lerp(library.FontColor, blend)
		end
		return library.FontColor:Lerp(library.AccentColor, blend)
	end

	local function refreshColors()
		local count = #labels
		local phase = gradientEnabled and ((os.clock() / gradientDuration) % 1) or 0
		for index, entry in ipairs(labels) do
			local color
			if gradientEnabled then
				local rowPosition = count <= 1 and 0.5 or (index - 1) / (count - 1)
				color = getGradientColor((rowPosition + phase) % 1)
			else
				color = library.AccentColor
			end
			entry.Label.TextColor3 = color
			entry.Sidebar.BackgroundColor3 = color
		end
	end

	refresh = function()
		for _, entry in ipairs(labels) do
			entry.Row:Destroy()
		end
		table.clear(labels)

		local active = {}
		for id, toggle in pairs(aztup_toggles) do
			if toggle.Type == "Toggle" and toggle.Value and toggle.ArrayList ~= false
				and toggle.TabName ~= "Settings" then
				local textWidth = math.ceil(library:GetLexendTextBounds(toggle.Name, lexend.bold, textSize))
				table.insert(active, { Id = id, Toggle = toggle, TextWidth = textWidth })
			end
		end
		table.sort(active, function(left, right)
			if left.TextWidth ~= right.TextWidth then
				if bottomSide then
					return left.TextWidth < right.TextWidth
				end
				return left.TextWidth > right.TextWidth
			end
			local leftName = string.lower(left.Toggle.Name)
			local rightName = string.lower(right.Toggle.Name)
			if leftName == rightName then
				return tostring(left.Id) < tostring(right.Id)
			end
			return leftName < rightName
		end)
		layout.VerticalAlignment = bottomSide and Enum.VerticalAlignment.Bottom or Enum.VerticalAlignment.Top

		local width = 0
		local rowHeight = math.ceil(textSize * 1.36)
		for index, entry in ipairs(active) do
			width = math.max(width, entry.TextWidth + 12)
			local horizontalAnchor = leftSide and 0 or 1
			local textAlignment = leftSide and Enum.TextXAlignment.Left or Enum.TextXAlignment.Right
			local row = library:Create("Frame", {
				BackgroundTransparency = 1,
				BorderSizePixel = 0,
				LayoutOrder = index,
				Size = UDim2.new(1, 0, 0, rowHeight),
				ZIndex = 81,
				Parent = list,
			})
			local background = library:Create("Frame", {
				AnchorPoint = Vector2.new(horizontalAnchor, 0),
				BackgroundColor3 = Color3.new(0, 0, 0),
				BackgroundTransparency = backgroundEnabled and 0.25 or 1,
				BorderSizePixel = 0,
				Position = UDim2.new(horizontalAnchor, 0, 0, 0),
				Size = UDim2.fromOffset(entry.TextWidth + 12, rowHeight),
				ZIndex = 81,
				Parent = row,
			})
			local sidebar = library:Create("Frame", {
				AnchorPoint = Vector2.new(horizontalAnchor, 0),
				BackgroundColor3 = library.AccentColor,
				BorderSizePixel = 0,
				Position = UDim2.new(horizontalAnchor, 0, 0, 0),
				Size = UDim2.new(0, 2, 1, 0),
				ZIndex = 83,
				Parent = row,
			})
			local label = library:CreateLabel({
				AnchorPoint = Vector2.new(horizontalAnchor, 0),
				BackgroundTransparency = 1,
				Position = UDim2.new(horizontalAnchor, leftSide and 5 or -5, 0, 0),
				Size = UDim2.fromOffset(entry.TextWidth + 2, rowHeight),
				FontFace = lexend.bold,
				Text = entry.Toggle.Name,
				TextColor3 = library.AccentColor,
				TextSize = textSize,
				TextStrokeColor3 = Color3.new(0, 0, 0),
				TextStrokeTransparency = 0.15,
				TextXAlignment = textAlignment,
				ZIndex = 82,
				Parent = row,
			})
			library:AddToRegistry(label, {
				TextStrokeColor3 = "Black",
			})
			table.insert(labels, {
				Row = row,
				Background = background,
				Label = label,
				Sidebar = sidebar,
			})
		end

		panel.Size = UDim2.fromOffset(math.max(100, width + 4), 16 + #labels * rowHeight)
		panel.Visible = visible and #labels > 0
		refreshColors()
	end

	local controller = {}
	function controller:SetVisible(value)
		visible = not not value
		refresh()
	end

	function controller:SetBackgroundEnabled(enabled)
		backgroundEnabled = not not enabled
		for _, entry in ipairs(labels) do
			entry.Background.BackgroundTransparency = backgroundEnabled and 0.25 or 1
		end
	end

	function controller:SetTextSize(value)
		textSize = math.clamp(math.floor(tonumber(value) or textSize), 10, 24)
		refresh()
	end

	function controller:SetGradient(enabled, duration)
		gradientEnabled = not not enabled
		gradientDuration = math.clamp(tonumber(duration) or gradientDuration, 1, 12)
		refreshColors()
	end

	function controller:SyncPlacement()
		leftSide = panel.AnchorPoint.X < 0.5
		bottomSide = panel.AnchorPoint.Y > 0.5
		library.ArrayListAnchorPoint = panel.AnchorPoint
		refresh()
	end

	library.ArrayListAnchorPoint = panel.AnchorPoint
	library.ArrayListController = controller

	library:GiveSignal(library.ToggleChanged.Event:Connect(function()
		if visible then
			refresh()
		end
	end))
	library:GiveSignal(RunService.RenderStepped:Connect(function()
		if not visible or not gradientEnabled or #labels == 0 then
			lastColorRefresh = 0
			return
		end
		local now = os.clock()
		if now - lastColorRefresh >= 1 / 15 then
			lastColorRefresh = now
			refreshColors()
		end
	end))
	library:GiveSignal(library.ScreenGui.Destroying:Connect(function()
		panel.Visible = false
	end))

	return controller
end
	end,
	["@src/ui/esp_preview"] = function()
local RunService = game:GetService("RunService")

return function(library)
	local screenGui = library.ScreenGui
	local frame = library:Create("Frame", {
		Name = "YSL_ESPPreview",
		AnchorPoint = Vector2.zero,
		BackgroundColor3 = library.MainColor,
		BackgroundTransparency = library.HudTransparency or 0.18,
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(0, 0),
		Size = UDim2.fromOffset(270, 230),
		Visible = true,
		ZIndex = 2,
		Parent = library.WindowHolder or screenGui,
	})
	library.ESPPreviewFrame = frame
	local previewStroke = library:Create("UIStroke", {
		Color = library.AccentColor,
		Thickness = 3,
		Transparency = 0.25,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		Parent = frame,
	})
	library:AddWindowGradientStroke(previewStroke)
	library:AddToRegistry(frame, {
		BackgroundColor3 = "MainColor",
	}, true)

	local header = library:Create("Frame", {
		BackgroundColor3 = library.BackgroundColor,
		BackgroundTransparency = math.clamp((library.HudTransparency or 0.18) - 0.08, 0, 0.8),
		BorderSizePixel = 0,
		Size = UDim2.new(1, 0, 0, 30),
		ZIndex = 181,
		Parent = frame,
	})
	library.ESPPreviewHeader = header
	library:AddToRegistry(header, {
		BackgroundColor3 = "BackgroundColor",
	}, true)
	local title = library:CreateLabel({
		BackgroundTransparency = 1,
		Position = UDim2.fromOffset(11, 0),
		Size = UDim2.new(1, -22, 1, 0),
		Text = "ESP Preview",
		TextColor3 = library.FontColor,
		TextSize = 12,
		TextXAlignment = Enum.TextXAlignment.Left,
		TextStrokeTransparency = 1,
		ZIndex = 182,
		Parent = header,
	})
	title.FontFace = lexend.bold
	library:AddToRegistry(title, {
		TextColor3 = "FontColor",
	}, true)

	local viewport = library:Create("ViewportFrame", {
		BackgroundColor3 = library.BackgroundColor,
		BackgroundTransparency = math.clamp((library.HudTransparency or 0.18) + 0.1, 0, 0.9),
		BorderSizePixel = 0,
		Position = UDim2.fromOffset(10, 38),
		Size = UDim2.new(1, -20, 1, -48),
		Ambient = Color3.fromRGB(170, 170, 170),
		LightColor = Color3.new(1, 1, 1),
		LightDirection = Vector3.new(-1, -1, -1),
		ZIndex = 181,
		Parent = frame,
	})
	library.ESPPreviewViewport = viewport
	library:AddToRegistry(viewport, {
		BackgroundColor3 = "BackgroundColor",
	}, true)

	local world = Instance.new("WorldModel")
	world.Parent = viewport
	local camera = Instance.new("Camera")
	camera.FieldOfView = 34
	camera.Parent = viewport
	viewport.CurrentCamera = camera

	local previewCharacter
	local previewBoundsSize
	local characterGeneration = 0
	local function showCharacter(character)
		characterGeneration += 1
		local generation = characterGeneration
		if previewCharacter then
			previewCharacter:Destroy()
			previewCharacter = nil
		end
		if not character or not character.Parent then
			return
		end

		local archivableStates = {}
		local function makeArchivable(instance)
			archivableStates[instance] = instance.Archivable
			instance.Archivable = true
		end
		makeArchivable(character)
		for _, descendant in ipairs(character:GetDescendants()) do
			makeArchivable(descendant)
		end
		local cloneSuccess, characterClone = pcall(function()
			return character:Clone()
		end)
		for instance, wasArchivable in pairs(archivableStates) do
			if instance.Parent then
				instance.Archivable = wasArchivable
			end
		end
		if not cloneSuccess then
			warn("[YSL Method] ESP preview character clone failed: " .. tostring(characterClone))
			return
		end
		if not characterClone then
			warn("[YSL Method] ESP preview character clone returned no model")
			return
		end

		characterClone.Name = "YSL_ESPPreviewCharacter"
		for _, descendant in ipairs(characterClone:GetDescendants()) do
			if descendant:IsA("Script") or descendant:IsA("LocalScript") or descendant:IsA("ModuleScript") then
				descendant:Destroy()
			elseif descendant:IsA("BasePart") then
				descendant.Anchored = true
				descendant.CanCollide = false
				descendant.CanQuery = false
				descendant.CanTouch = false
			elseif descendant:IsA("Humanoid") then
				descendant.DisplayDistanceType = Enum.HumanoidDisplayDistanceType.None
			elseif descendant:IsA("BillboardGui") or descendant:IsA("ProximityPrompt") then
				descendant:Destroy()
			end
		end

		characterClone.Parent = world
		local boundsCFrame, boundsSize = characterClone:GetBoundingBox()
		if boundsSize.Y <= 0 then
			characterClone:Destroy()
			return
		end
		local rootPart = characterClone:FindFirstChild("HumanoidRootPart")
		local lookVector = rootPart and rootPart.CFrame.LookVector or boundsCFrame.LookVector
		local flatLook = Vector3.new(lookVector.X, 0, lookVector.Z)
		local yawCorrection = flatLook.Magnitude > 0.001
			and -math.atan2(flatLook.X, flatLook.Z)
			or math.pi
		local targetBounds = CFrame.new(0, boundsSize.Y / 2, 0)
			* CFrame.Angles(0, yawCorrection, 0)
			* boundsCFrame.Rotation
		local pivotDelta = targetBounds * boundsCFrame:Inverse()
		characterClone:PivotTo(pivotDelta * characterClone:GetPivot())

		if generation ~= characterGeneration then
			characterClone:Destroy()
			return
		end
		previewCharacter = characterClone
		previewBoundsSize = boundsSize
		local distance = boundsSize.Y / (2 * math.tan(math.rad(camera.FieldOfView / 2))) * 1.2
		camera.CFrame = CFrame.lookAt(
			Vector3.new(0, boundsSize.Y / 2, distance),
			Vector3.new(0, boundsSize.Y / 2, 0)
		)
	end

	local localPlayer = game:GetService("Players").LocalPlayer
	if localPlayer then
		library:GiveSignal(localPlayer.CharacterAdded:Connect(function(character)
			showCharacter(character)
			localPlayer.CharacterAppearanceLoaded:Once(function(loadedCharacter)
				if loadedCharacter == character and localPlayer.Character == character then
					showCharacter(character)
				end
			end)
		end))
		if localPlayer.Character then
			showCharacter(localPlayer.Character)
		end
	end

	local boxOutline = library:Create("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundTransparency = 1,
		BorderSizePixel = 0,
		Position = UDim2.new(0.5, 0, 0.5, 0),
		Size = UDim2.new(0.42, 4, 0.78, 4),
		Visible = false,
		ZIndex = 182,
		Parent = viewport,
	})
	local boxOutlineStroke = library:Create("UIStroke", {
		Color = Color3.new(0, 0, 0),
		Transparency = 0.15,
		Thickness = 3,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		LineJoinMode = Enum.LineJoinMode.Miter,
		Parent = boxOutline,
	})
	local box = library:Create("Frame", {
		AnchorPoint = Vector2.new(0.5, 0.5),
		BackgroundColor3 = library.AccentColor,
		BackgroundTransparency = 0.97,
		BorderSizePixel = 0,
		Position = UDim2.new(0.5, 0, 0.5, 0),
		Size = UDim2.new(0.42, 0, 0.78, 0),
		Visible = false,
		ZIndex = 183,
		Parent = viewport,
	})
	local boxStroke = library:Create("UIStroke", {
		Color = library.AccentColor,
		Thickness = 1.5,
		Transparency = 0.08,
		ApplyStrokeMode = Enum.ApplyStrokeMode.Border,
		LineJoinMode = Enum.LineJoinMode.Miter,
		Parent = box,
	})

	local healthTrack = library:Create("Frame", {
		BackgroundColor3 = Color3.fromRGB(8, 12, 14),
		BackgroundTransparency = 0.08,
		BorderSizePixel = 0,
		AnchorPoint = Vector2.new(0.5, 0.5),
		Position = UDim2.new(0.25, 0, 0.5, 0),
		Size = UDim2.new(0, 8, 0.72, 0),
		Visible = false,
		ZIndex = 184,
		Parent = viewport,
	})
	library:Create("UIStroke", {
		Color = Color3.new(0, 0, 0),
		Transparency = 0.08,
		Thickness = 1.5,
		Parent = healthTrack,
	})
	local healthFill = library:Create("Frame", {
		AnchorPoint = Vector2.new(0, 1),
		BackgroundColor3 = Color3.fromRGB(187, 255, 181),
		BorderSizePixel = 0,
		Position = UDim2.fromScale(0, 1),
		Size = UDim2.new(1, 0, 1, 0),
		ZIndex = 185,
		Parent = healthTrack,
	})
	local healthGradient = library:Create("UIGradient", {
		Color = ColorSequence.new(
			Color3.fromRGB(187, 255, 181),
			Color3.fromRGB(187, 255, 181):Lerp(Color3.new(1, 1, 1), 0.2)
		),
		Rotation = -90,
		Parent = healthFill,
	})
	local healthDividers = {}
	for _, fraction in ipairs({ 0.2, 0.4, 0.6, 0.8 }) do
		local divider = library:Create("Frame", {
			AnchorPoint = Vector2.new(0, 0.5),
			BackgroundColor3 = Color3.fromRGB(8, 12, 14),
			BackgroundTransparency = 0.18,
			BorderSizePixel = 0,
