			if avatarDamageFlash.Parent then
				TweenService:Create(avatarDamageFlash, TweenInfo.new(0.55, Enum.EasingStyle.Quad, Enum.EasingDirection.InOut), {
					BackgroundTransparency = 1,
				}):Play()
			end
		end)
	end

	local function validTarget(player)
		if not player or player == LocalPlayer or player.Parent ~= Players then
			return nil
		end
		if hideTeammates and LocalPlayer.Team and player.Team == LocalPlayer.Team then
			return nil
		end
		local character = player.Character
		local humanoid = character and character:FindFirstChildOfClass("Humanoid")
		local head = character and character:FindFirstChild("Head")
		if not humanoid or humanoid.Health <= 0 or not head or not head:IsA("BasePart") then
			return nil
		end
		return humanoid
	end

	local function findNearestPlayer()
		local localCharacter = LocalPlayer.Character
		local localRoot = localCharacter and localCharacter:FindFirstChild("HumanoidRootPart")
		if not localRoot then
			return nil
		end
		local nearest
		local nearestDistance = math.huge
		for _, player in ipairs(Players:GetPlayers()) do
			local humanoid = validTarget(player)
			local character = humanoid and player.Character
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if root and root:IsA("BasePart") then
				local distance = (root.Position - localRoot.Position).Magnitude
				if distance < nearestDistance then
					nearest = player
					nearestDistance = distance
				end
			end
		end
		return nearest
	end

	local function updateVisibility()
		outer.Visible = enabled and (library.Toggled or currentHumanoid ~= nil)
	end

	local function restoreManualPosition()
		settingFollowPosition = true
		outer.AnchorPoint = Vector2.zero
		outer.Position = manualPosition
		settingFollowPosition = false
	end

	local function updateFollowPosition()
		if not followTarget then
			return
		end
		local camera = workspace.CurrentCamera
		local character = currentPlayer and currentPlayer.Character
		local targetPart = character and (character:FindFirstChild("Head")
			or character:FindFirstChild("HumanoidRootPart"))
		if not camera or not targetPart or not targetPart:IsA("BasePart") then
			restoreManualPosition()
			return
		end

		local screenPoint, onScreen = camera:WorldToViewportPoint(targetPart.Position)
		if not onScreen or screenPoint.Z <= 0 then
			restoreManualPosition()
			return
		end
		local viewport = camera.ViewportSize
		local halfWidth = outer.AbsoluteSize.X * 0.5
		local halfHeight = outer.AbsoluteSize.Y * 0.5
		local scale = library:GetInstanceScale(outer)
		local gap = 16
		local rightCenter = screenPoint.X + halfWidth + gap
		local leftCenter = screenPoint.X - halfWidth - gap
		local preferredCenter = rightCenter + halfWidth <= viewport.X - 8 and rightCenter or leftCenter
		local x = math.clamp(
			preferredCenter,
			halfWidth + 8,
			math.max(halfWidth + 8, viewport.X - halfWidth - 8)
		)
		local y = math.clamp(
			screenPoint.Y,
			halfHeight + 8,
			math.max(halfHeight + 8, viewport.Y - halfHeight - 8)
		)
		settingFollowPosition = true
		outer.AnchorPoint = Vector2.new(0.5, 0.5)
		outer.Position = UDim2.fromOffset(x / scale, y / scale)
		settingFollowPosition = false
	end

	local function setFollowTarget(value)
		followTarget = not not value
		if followTarget then
			manualPosition = library.TargetHUDManualPosition or outer.Position
		else
			restoreManualPosition()
		end
	end

	local function setTarget(player)
		currentPlayer = player
		currentHumanoid = player and validTarget(player) or nil
		updateVisibility()
		lastHealth = currentHumanoid and currentHumanoid.Health or nil
		local initialRatio = currentHumanoid
			and math.clamp(currentHumanoid.Health / math.max(currentHumanoid.MaxHealth, 1), 0, 1)
			or 0
		lastHealthRatio = initialRatio
		healthFill.Size = UDim2.new(initialRatio, 0, 1, 0)
		damageFill.Position = UDim2.fromScale(0, 0)
		damageFill.Size = UDim2.fromScale(1, 1)
		thumbnailGeneration += 1
		local generation = thumbnailGeneration
		if not player or not currentHumanoid then
			avatar.Image = ""
			nameLabel.Text = "No target"
			healthLabel.Text = "-- / -- HP"
			healthFill.Size = UDim2.fromScale(0, 1)
			damageFill.Position = UDim2.fromScale(0, 0)
			damageFill.Size = UDim2.fromScale(1, 1)
			return
		end

		nameLabel.Text = player.DisplayName
		task.spawn(function()
			local success, image = pcall(function()
				local content, _ = Players:GetUserThumbnailAsync(
					player.UserId,
					Enum.ThumbnailType.HeadShot,
					Enum.ThumbnailSize.Size150x150
				)
				return content
			end)
			if success and generation == thumbnailGeneration and currentPlayer == player then
				avatar.Image = image
			end
		end)
	end

	local function updateTargetHUD(deltaTime)
		if not enabled then
			return
		end
		if currentHumanoid then
			updateFollowPosition()
		end
		updateElapsed += deltaTime
		if updateElapsed < 0.1 then
			return
		end
		updateElapsed %= 0.1

		local lockedTarget
		if type(library.GetTargetHUDTarget) == "function" then
			local success, result = pcall(library.GetTargetHUDTarget)
			if success then
				lockedTarget = result
			else
				warn("[YSL Method] TargetHUD lock target lookup failed: " .. tostring(result))
			end
		end
		local target = validTarget(lockedTarget) and lockedTarget or findNearestPlayer()
		local humanoid = target and validTarget(target)
		if target ~= currentPlayer or humanoid ~= currentHumanoid then
			setTarget(target)
			humanoid = currentHumanoid
		end
		if not humanoid then
			if currentPlayer then
				setTarget(nil)
			end
			if followTarget then
				restoreManualPosition()
			end
			updateVisibility()
			return
		end
		updateFollowPosition()
		updateVisibility()

		local maxHealth = math.max(humanoid.MaxHealth, 1)
		local health = math.clamp(humanoid.Health, 0, maxHealth)
		local ratio = health / maxHealth
		healthLabel.Text = string.format("%d / %d HP", math.floor(health + 0.5), math.floor(maxHealth + 0.5))

		if lastHealth and health < lastHealth then
			burstDamageParticles(lastHealthRatio or ratio)
			flashAvatarDamage()
		end
		if ratio ~= lastHealthRatio then
			TweenService:Create(healthFill, TweenInfo.new(0.18, Enum.EasingStyle.Quad, Enum.EasingDirection.Out), {
				Size = UDim2.new(ratio, 0, 1, 0),
			}):Play()
			lastHealthRatio = ratio
		end
		lastHealth = health
	end

	local function setEnabled(value)
		enabled = not not value
		updateVisibility()
		if updateConnection then
			updateConnection:Disconnect()
			updateConnection = nil
		end
		if enabled then
			updateElapsed = 0
			updateConnection = RunService.Heartbeat:Connect(updateTargetHUD)
		else
			setTarget(nil)
		end
	end

	if library.OnToggledChanged then
		menuToggleConnection = library.OnToggledChanged.Event:Connect(updateVisibility)
	end

	library:MakeDraggable(outer, 28, true)
	groupbox:AddToggle("YSL_TargetHUDEnabled", {
		Text = "TargetHUD",
		Tooltip = "When enabled, stays visible while the menu is open for positioning, then only shows with a valid target.",
		Default = false,
		Callback = setEnabled,
	})
	groupbox:AddToggle("YSL_TargetHUDHideTeammates", {
		Text = "Hide teammates",
		Tooltip = "Excludes players on your Roblox team from TargetHUD selection.",
		Default = false,
		Callback = function(value)
			hideTeammates = not not value
		end,
	})
	groupbox:AddToggle("YSL_TargetHUDFollowTarget", {
		Text = "Follow targeted player",
		Tooltip = "Pins the TargetHUD above the current target on screen. When the target is off-screen, it returns to its saved position.",
		Default = false,
		Callback = setFollowTarget,
	})

	library:OnUnload(function()
		setEnabled(false)
		if positionChangedConnection then
			positionChangedConnection:Disconnect()
			positionChangedConnection = nil
		end
		if healthGradientTween then
			healthGradientTween:Cancel()
			healthGradientTween = nil
		end
		if damageGradientTween then
			damageGradientTween:Cancel()
			damageGradientTween = nil
		end
		if nameGradientTween then
			nameGradientTween:Cancel()
			nameGradientTween = nil
		end
		if menuToggleConnection then
			menuToggleConnection:Disconnect()
			menuToggleConnection = nil
		end
		if outer.Parent then
			outer:Destroy()
		end
		if library.TargetHUDFrame == outer then
			library.TargetHUDFrame = nil
			library.TargetHUDManualPosition = nil
		end
	end)
end
	end,
	["@src/ui/aba_esp"] = function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local CollectionService = game:GetService("CollectionService")
local LocalPlayer = Players.LocalPlayer
local ESP_ASSET_ID = "rbxassetid://99131262255411"

return function(library, groupbox, context, preview)
	local settings = {
		Enabled = false,
		Health = false,
		Ultimate = false,
		Moves = false,
		Info = false,
		LocalPlayer = false,
		Enemies = true,
		TeamCheck = false,
		Scale = true,
		ScaleMultiplier = 1,
		Box = false,
	}
	local records = {}
	local playerConnections = {}
	local assetTemplate
	local loadingAsset = false

	local function notify(message)
		if context and type(context.SetStatus) == "function" then
			context.SetStatus(message)
		else
			warn("[YSL Method] " .. message)
		end
	end

	local function refreshPreview()
		if preview then
			preview:SetOptions({
				Boxes = settings.Box,
				Health = settings.Health,
				Ultimate = settings.Ultimate,
				Moves = settings.Moves,
				Info = settings.Info,
				Names = settings.Info,
				SecondUltimate = settings.Ultimate,
			})
		end
	end
	refreshPreview()

	local function cleanupRecord(record)
		if record.Connection then
			record.Connection:Disconnect()
		end
		if record.CharacterAddedConnection then
			record.CharacterAddedConnection:Disconnect()
		end
		if record.CharacterRemovingConnection then
			record.CharacterRemovingConnection:Disconnect()
		end
		if record.Object then
			record.Object:Destroy()
		end
	end

	local function clearRecords()
		for player, record in pairs(records) do
			cleanupRecord(record)
			records[player] = nil
		end
	end

	local function disconnectPlayerConnections()
		for _, connection in pairs(playerConnections) do
			connection:Disconnect()
		end
		table.clear(playerConnections)
	end

	local function getSecondModeValue(player)
		local value = player:FindFirstChild("SecondBar")
		local choices = {
			{ "SungJinWooBar", Color3.fromRGB(53, 211, 255) },
			{ "BrolyBar", nil },
			{ "GatesBar", Color3.fromRGB(149, 0, 255) },
			{ "PucciPieces", Color3.fromRGB(184, 143, 255) },
			{ "AstaBar", Color3.fromRGB(255, 48, 51) },
			{ "RagnaBar", Color3.fromRGB(140, 180, 255) },
			{ "RoomBar", Color3.fromRGB(116, 211, 255) },
			{ "BloodBar", Color3.fromRGB(57, 0, 0) },
		}
		for _, choice in ipairs(choices) do
			local candidate = player:FindFirstChild(choice[1])
			if candidate then
				return candidate, choice[2]
			end
		end
		local character = player.Character
		if character then
			local indra = character:FindFirstChild("IndraArrowBar")
			if indra then
				return indra, Color3.fromRGB(53, 28, 108)
			end
			local hamon = character:FindFirstChild("HamonMeter")
			if hamon then
				return hamon, Color3.fromRGB(149, 149, 0)
			end
		end
		return value
	end

	local function grabSlot(config)
		for _, child in ipairs(config:GetChildren()) do
			if string.find(child.Name, "Slot", 1, true) then
				return child
			elseif child.Name == "M2Skill" then
				return { Name = "Slot5" }
			end
		end
		return nil
	end

	local function getSlotIndex(config, index)
		local slot = grabSlot(config)
		local slotNumber = slot and string.match(slot.Name, "Slot(%d+)")
		return slotNumber or tostring(index - 4)
	end

	local function getMaxValue(valueObject)
		local propertySuccess, propertyMaximum = pcall(function()
			return valueObject.MaxValue
		end)
		if propertySuccess and type(propertyMaximum) == "number" and propertyMaximum > 0 then
			return propertyMaximum
		end

		local maximum = valueObject:GetAttribute("MaxValue")
		local maxValueObject = valueObject:FindFirstChild("MaxValue")
		if maxValueObject and maxValueObject:IsA("ValueBase") then
			maximum = maxValueObject.Value
		end
		return type(maximum) == "number" and maximum > 0 and maximum or 100
	end

	local function setInfoVisibility(info)
		for _, name in ipairs({ "Maka", "BlackFlash", "Mahoraga", "Crow", "Boa", "Iframe", "Nanami" }) do
			local item = info:FindFirstChild(name)
			if item then
				item.Visible = false
			end
		end
	end

	local function attachPlayer(player)
		if records[player] then
			cleanupRecord(records[player])
			records[player] = nil
		end
		if not assetTemplate then
			return
		end

		local gui = assetTemplate:Clone()
		gui.Name = "YSL_ABA_ESP_" .. tostring(player.UserId)
		gui.Enabled = false
		gui.ResetOnSpawn = false
		gui.Parent = game:GetService("CoreGui")

		local frame = gui:FindFirstChild("Target")
		local health = frame and frame:FindFirstChild("Health")
		local mode = frame and frame:FindFirstChild("Mode")
		local info = frame and frame:FindFirstChild("Info")
		local moves = frame and frame:FindFirstChild("Moves")
		if not frame or not health or not mode or not info or not moves then
			gui:Destroy()
			notify("ABA ESP asset is missing one or more expected HUD elements")
			return
		end

		local modeInfo = {
			Maka = info:FindFirstChild("Maka"),
			BlackFlash = info:FindFirstChild("BlackFlash"),
			Mahoraga = info:FindFirstChild("Mahoraga"),
			Crow = info:FindFirstChild("Crow"),
			Boa = info:FindFirstChild("Boa"),
			Iframe = info:FindFirstChild("Iframe"),
			Nanami = info:FindFirstChild("Nanami"),
		}
		local ultimate = mode:FindFirstChild("Ultimate")
		local ultimate2 = mode:FindFirstChild("Ultimate2")
		local healthBar = health:FindFirstChild("Bar")
		local ultimateBar = ultimate and ultimate:FindFirstChild("Bar")
		if not ultimate or not ultimate2 or not healthBar or not ultimateBar then
			gui:Destroy()
			notify("ABA ESP asset is missing health or ultimate bars")
			return
		end
		setInfoVisibility(info)

		local connection = RunService.RenderStepped:Connect(function()
			local character = player.Character
			local humanoid = character and character:FindFirstChildOfClass("Humanoid")
			local root = character and character:FindFirstChild("HumanoidRootPart")
			if not character or not humanoid or not root or humanoid.Health <= 0 then
				gui.Enabled = false
				return
			end

			local isLocalPlayer = player == LocalPlayer
			gui.Enabled = isLocalPlayer and settings.LocalPlayer or (not isLocalPlayer and settings.Enemies)
			if not gui.Enabled then
				return
			end
			frame.Visible = not (
				settings.TeamCheck
				and not isLocalPlayer
				and player.Team ~= nil
				and LocalPlayer.Team ~= nil
				and player.Team == LocalPlayer.Team
			)
			if not frame.Visible then
				return
			end

			if gui.Adornee ~= root then
				gui.Adornee = root
			end
			local backpack = player:FindFirstChildOfClass("Backpack") or player:FindFirstChild("Backpack")
			if not backpack then
				return
			end
			local secondModeValue, secondModeColor = getSecondModeValue(player)
			local charge = player:FindFirstChild("Charge")
			local camera = workspace.CurrentCamera
			local sizeMultiplier = settings.Scale
				and (1 + (math.clamp(settings.ScaleMultiplier, 1, 5) - 1) * 0.25)
				or 1
			local viewportHeight = camera and camera.ViewportSize.Y or 720
			local basePixelSize = settings.Scale
				and math.clamp(viewportHeight * 0.5, 350, 420)
				or 380
			local distanceScale = 1
			if camera then
				local distance = (camera.CFrame.Position - root.Position).Magnitude
				distanceScale = math.clamp(24 / math.max(distance, 24), 0.28, 1)
			end
			local guiPixelSize = math.floor(basePixelSize * sizeMultiplier * distanceScale + 0.5)

			mode.Visible = settings.Ultimate
			health.Visible = settings.Health
			moves.Visible = settings.Moves
			info.Visible = settings.Info
			for _, child in ipairs(frame:GetChildren()) do
				if child:IsA("UIStroke") then
					child.Enabled = settings.Box
				end
			end

			local maka = modeInfo.Maka
			local makaValue = player:FindFirstChild("KishinEgg")
			if maka then
				maka.Visible = settings.Info and makaValue ~= nil
				if maka.Visible and maka.AmountText then
					maka.AmountText.Text = tostring(makaValue.Value)
				end
			end

			local blackFlash = modeInfo.BlackFlash
			local blackFlashValue = character:FindFirstChild("BlackFlashRequirement")
			if blackFlash then
				blackFlash.Visible = settings.Info and blackFlashValue ~= nil
				if blackFlash.Visible and blackFlash.AmountText then
					local maximum = getMaxValue(blackFlashValue)
					blackFlash.AmountText.Text = string.format(
						"%d%%",
						math.floor(math.clamp(blackFlashValue.Value / maximum, 0, 1) * 100)
					)
				end
			end

			local mahoraga = modeInfo.Mahoraga
			local wheelSpins = character:FindFirstChild("WheelSpins")
			if mahoraga then
				mahoraga.Visible = settings.Info and wheelSpins ~= nil
				if mahoraga.Visible and mahoraga.AmountText then
					mahoraga.AmountText.Text = tostring(wheelSpins.Value)
				end
			end

			local crow = modeInfo.Crow
			if crow then
				crow.Visible = settings.Info and character:FindFirstChild("CrowClone") ~= nil
			end
			local iframe = modeInfo.Iframe
			if iframe then
				iframe.Visible = settings.Info
					and (character:FindFirstChild("i") ~= nil or character:FindFirstChild("ip") ~= nil)
			end
			local nanami = modeInfo.Nanami
			local ratioCounter = character:GetAttribute("RatioCounter")
			if nanami then
				nanami.Visible = settings.Info and type(ratioCounter) == "number" and ratioCounter > 0
				if nanami.Visible and nanami.AmountText then
					nanami.AmountText.Text = tostring(ratioCounter)
				end
			end
			local boa = modeInfo.Boa
			local charmedAt = character:GetAttribute("CharmedAt")
			if boa then
				boa.Visible = settings.Info and type(charmedAt) == "number"
				if boa.Visible and boa.AmountText then
					boa.AmountText.Text = string.format("%.1f", math.max(0, os.clock() - charmedAt))
				end
			end

			local m2Available = backpack:FindFirstChild("M2Skill", true) ~= nil
			local slotFive = moves:FindFirstChild("5")
			if slotFive then
				slotFive.Visible = settings.Moves and m2Available
			end
			for index, move in ipairs(backpack:GetChildren()) do
				if move:IsA("Configuration") then
					local config = move:FindFirstChild(".Config")
					local moveFrame = moves:FindFirstChild(getSlotIndex(config or move, index))
					if config and moveFrame then
						local infoTag = moveFrame:FindFirstChild("InfoTag")
						local skillHunter = character:FindFirstChild("SkillHunter")
						local hunterName = skillHunter and skillHunter:GetAttribute("Move")
						local hunterGuardBreak = skillHunter and skillHunter:GetAttribute("Selected") == "Guardbreak"
						local hasGuardBreak = CollectionService:HasTag(move, "Guardbreaks") or hunterGuardBreak
						if infoTag then
							infoTag.Text = "Guardbreaks"
							infoTag.Visible = hasGuardBreak
						end
						local stroke = moveFrame:FindFirstChildOfClass("UIStroke")
						if stroke then
							stroke.Thickness = 0
						end
						local teamColor = player.Team and player.TeamColor.Color or Color3.fromRGB(223, 43, 43)
						local usingSkill = character:FindFirstChild("UsingSkill")
						if usingSkill and move.Name == usingSkill.Value then
							teamColor = Color3.new(1, 1, 1)
						end
						local cover = moveFrame:FindFirstChild("DisableCover")
						if cover then
							cover.Visible = true
							cover.Size = UDim2.fromScale(
								1,
								math.clamp(1 - (move:GetAttribute("COOLDOWN") or 20) / 20, 0, 1)
							)
						end
						local image = moveFrame:FindFirstChild("ImageLabel")
						if image then
							image.ImageColor3 = teamColor
						end
						local textLabel = moveFrame:FindFirstChild("TextLabel")
						local newName = move:FindFirstChild("NewName", true)
						if textLabel then
							textLabel.Text = hunterName or (newName and newName.Value) or move.Name
						end
						moveFrame.Visible = settings.Moves
					end
				end
			end

			local secondModeBar = ultimate2:FindFirstChild("Bar")
			if secondModeValue and secondModeBar then
				ultimate2.Visible = settings.Ultimate
				secondModeBar.Size = UDim2.fromScale(
					math.clamp(secondModeValue.Value / getMaxValue(secondModeValue), 0, 1),
					0.78
				)
				secondModeBar.BackgroundColor3 = secondModeColor or Color3.fromRGB(149, 0, 255)
			else
				ultimate2.Visible = false
			end

			if charge then
				ultimateBar.BackgroundColor3 = character:FindFirstChild("IfDied")
						and (character:FindFirstChild("SwordWeld", true)
							and Color3.fromRGB(164, 53, 255)
							or Color3.new(1, 1, 1))
					or Color3.fromRGB(255, 0, 0)
				ultimateBar.Size = UDim2.fromScale(
					math.clamp(charge.Value / getMaxValue(charge), 0, 1),
					0.912
				)
			end
			healthBar.Size = UDim2.fromScale(
				math.clamp(humanoid.Health / math.max(humanoid.MaxHealth, 1), 0, 1),
				1
			)
			gui.Size = UDim2.fromOffset(guiPixelSize, guiPixelSize)
		end)

		local record = {
			Object = gui,
			Connection = connection,
		}
		records[player] = record
		record.CharacterAddedConnection = player.CharacterAdded:Connect(function(character)
			gui.Enabled = false
			gui.Adornee = nil
			task.spawn(function()
				local humanoid = character:WaitForChild("Humanoid", 10)
				local root = character:WaitForChild("HumanoidRootPart", 10)
				if not humanoid or not root or records[player] ~= record or not settings.Enabled then
					return
				end
				attachPlayer(player)
			end)
		end)
		record.CharacterRemovingConnection = player.CharacterRemoving:Connect(function()
			gui.Enabled = false
			gui.Adornee = nil
		end)
	end

	local function loadAsset()
		if assetTemplate then
			return true
		end
		if loadingAsset then
			return false, "ABA ESP asset load is already in progress"
		end
		if type(game.GetObjects) ~= "function" then
			return false, "This executor does not support loading the ABA ESP GUI asset"
		end
		loadingAsset = true
		local success, result = pcall(function()
			local objects = game:GetObjects(ESP_ASSET_ID)
			assert(type(objects) == "table" and objects[1], "ABA ESP GUI asset returned no objects")
			return objects[1]
		end)
		loadingAsset = false
		if not success then
			return false, "Could not load ABA ESP GUI asset: " .. tostring(result)
		end
		assetTemplate = result
		assetTemplate.Name = "YSL_ABA_ESP_Template"
		assetTemplate.Enabled = false
		return true
	end

	local function setEnabled(value)
		settings.Enabled = not not value
		disconnectPlayerConnections()
		clearRecords()
		if not settings.Enabled then
			return
		end

		local loaded, loadError = loadAsset()
		if not loaded then
			settings.Enabled = false
			notify(loadError)
			local toggle = aztup_toggles.ABA_ESPEnabled
			if toggle and toggle.Value then
				task.defer(function()
					if toggle.Value then
						toggle:SetValue(false)
					end
				end)
			end
			return
		end
		if assetTemplate.Parent then
			assetTemplate.Parent = nil
		end

		for _, player in ipairs(Players:GetPlayers()) do
			attachPlayer(player)
		end
		playerConnections.PlayerAdded = Players.PlayerAdded:Connect(attachPlayer)
		playerConnections.PlayerRemoving = Players.PlayerRemoving:Connect(function(player)
			if records[player] then
				cleanupRecord(records[player])
				records[player] = nil
			end
		end)
	end

	local toggle = groupbox:AddToggle("ABA_ESPEnabled", {
		Text = "ESP",
		Default = false,
		Tooltip = "Shows the full ABA ESP HUD with health, ultimate, move, and character information.",
		Callback = setEnabled,
	})
	toggle:AddKeyPicker("ABA_ESPKey", {
		Default = "F8",
		Mode = "Toggle",
		SyncToggleState = true,
		Text = "ABA ESP",
	})
	groupbox:AddToggle("ABA_ESPHP", {
		Text = "ESP Healthbar",
		Default = false,
		Callback = function(value)
			settings.Health = not not value
			refreshPreview()
		end,
	})
	groupbox:AddToggle("ABA_ESPULT", {
		Text = "ESP Ultimates",
		Default = false,
		Callback = function(value)
			settings.Ultimate = not not value
			refreshPreview()
		end,
	})
	groupbox:AddToggle("ABA_ESPMOVES", {
		Text = "ESP Moves",
		Default = false,
		Callback = function(value)
			settings.Moves = not not value
			refreshPreview()
		end,
	})
	groupbox:AddToggle("ABA_ESPINFO", {
		Text = "ESP Info",
		Default = false,
		Callback = function(value)
			settings.Info = not not value
			refreshPreview()
		end,
	})
	groupbox:AddToggle("ABA_ESPLP", {
		Text = "ESP Local Player",
		Default = false,
		Callback = function(value)
			settings.LocalPlayer = not not value
		end,
	})
	groupbox:AddToggle("ABA_ESPENEMY", {
		Text = "ESP others",
		Default = true,
		Callback = function(value)
			settings.Enemies = not not value
		end,
	})
	groupbox:AddToggle("ABA_ESPTEAM", {
		Text = "ESP Team check",
		Default = false,
		Callback = function(value)
			settings.TeamCheck = not not value
		end,
	})
	groupbox:AddToggle("ABA_ESPSCALE", {
		Text = "ESP Scaling",
		Tooltip = "Adjusts canvas size for screen height and distance, and enables the size multiplier.",
		Default = true,
		Callback = function(value)
			settings.Scale = not not value
		end,
	})
	groupbox:AddToggle("ABA_ESPBOX", {
		Text = "ESP Box",
		Default = false,
		Callback = function(value)
			settings.Box = not not value
			refreshPreview()
		end,
	})
	groupbox:AddSlider("ABA_ESPMultiplier", {
		Text = "HUD size multiplier",
		Default = 1,
		Min = 1,
		Max = 5,
		Rounding = 1,
		Callback = function(value)
			settings.ScaleMultiplier = math.clamp(tonumber(value) or 1, 1, 5)
		end,
	})

	library:OnUnload(function()
		setEnabled(false)
		if assetTemplate then
			assetTemplate:Destroy()
			assetTemplate = nil
		end
	end)
end
	end,
	["@src/ui/tabs/Visuals"] = function()
local createAmbience = require("@src/ui/ambience")
local createVisuals = require("@src/ui/visuals")
local createArrayList = require("@src/ui/arraylist")
local createEspPreview = require("@src/ui/esp_preview")
local setupTargetHUD = require("@src/ui/target_hud")
local setupABAESP = require("@src/ui/aba_esp")

local function setupVisuals(funTab, playerTab, context, settingsTab)
	settingsTab = settingsTab or funTab
	local library = context.Library
	local ambience = createAmbience(library)
	local visuals
	if not context.ShowcaseOnly then
		visuals = createVisuals(library)
	end
	local arrayList = createArrayList(library)
	local espPreview = createEspPreview(library)

	ambience:SetMode("Rain")
	local atmosphere = settingsTab:AddLeftGroupbox("Screen Effect")
	atmosphere:AddDropdown("YSL_Ambience", {
		Text = "Screen effect",
		Values = { "Off", "Rain", "Snow" },
		Default = "Rain",
		Callback = function(value)
			ambience:SetMode(value)
		end,
	})
	atmosphere:AddSlider("YSL_AmbienceIntensity", {
		Text = "Rain / snow intensity",
		Default = 36,
		Min = 12,
		Max = 48,
		Rounding = 0,
		Callback = function(value)
			ambience:SetIntensity(value)
		end,
	})

	if not context.ShowcaseOnly and context.GameName == "ABA" then
		setupABAESP(library, playerTab:AddLeftGroupbox("ABA Player ESP"), context, espPreview)
	else
	if not context.ShowcaseOnly then
		espPreview:SetPlayerESP(visuals.PlayerESP)
	end
	local playerEsp = playerTab:AddLeftGroupbox(context.ShowcaseOnly and "ESP Preview Controls" or "Player ESP")
	if context.ShowcaseOnly then
		playerEsp:AddLabel("Showcase placeholders only; these do not affect other players.", true)
	end
	playerEsp:AddToggle("YSL_PlayerESPEnabled", {
		Text = "Player ESP",
		SettingsFlags = {
			"YSL_PlayerESPNameColor",
			"YSL_PlayerESPNameOutlineColor",
			"YSL_PlayerESPHealthbar",
			"YSL_PlayerESPBoxes",
			"YSL_PlayerESPNametags",
			"YSL_PlayerESPFadeout",
			"YSL_PlayerESPFadeoutHover",
			"YSL_PlayerESPTextSize",
			"YSL_PlayerESPFadeDistance",
			"YSL_PlayerESPMaxDistance",
			"YSL_PlayerESPTags",
			"YSL_PlayerESPDistanceFormat",
			"YSL_PlayerESPUpdateRate",
		},
		Tooltip = "Enables player names, health bars, and theme-colored boxes.",
		Default = false,
		Callback = function(enabled)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetEnabled(enabled)
			end
			espPreview:SetOptions({
				Boxes = enabled,
				Health = enabled,
				Names = enabled,
			})
		end,
	})
	playerEsp:AddLabel("Name color"):AddColorPicker("YSL_PlayerESPNameColor", {
		Default = Color3.fromRGB(205, 214, 244),
		Title = "Player name color",
		Callback = function(color)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetNameColor(color)
			end
		end,
	})
	playerEsp:AddLabel("Name outline color"):AddColorPicker("YSL_PlayerESPNameOutlineColor", {
		Default = Color3.new(0, 0, 0),
		Title = "Player name outline color",
		Callback = function(color)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetNameOutlineColor(color)
			end
		end,
	})
	playerEsp:AddToggle("YSL_PlayerESPHealthbar", {
		Text = "Player healthbars",
		Tooltip = "Shows the segmented vertical health bar beside each player.",
		Default = false,
		Callback = function(enabled)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetHealthbar(enabled)
			end
			espPreview:SetOptions({ Health = enabled })
		end,
	})
	playerEsp:AddToggle("YSL_PlayerESPBoxes", {
		Text = "Player boxes",
		Tooltip = "Draws an outlined box around each player.",
		Default = false,
		Callback = function(enabled)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetBoxes(enabled)
			end
			espPreview:SetOptions({ Boxes = enabled })
		end,
	})
	playerEsp:AddToggle("YSL_PlayerESPNametags", {
		Text = "Player names",
		Tooltip = "Shows selected player tags above and below each player.",
		Default = true,
		Callback = function(enabled)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetNames(enabled)
			end
			espPreview:SetOptions({ Names = enabled })
		end,
	})
	playerEsp:AddToggle("YSL_PlayerESPFadeout", {
		Text = "Player fadeout",
		Tooltip = "Fades player labels after the configured distance.",
		Default = false,
		Callback = function(enabled)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetFadeout(enabled)
			end
		end,
	})
	playerEsp:AddToggle("YSL_PlayerESPFadeoutHover", {
		Text = "Fade less near cursor",
		Tooltip = "Reduces fadeout for labels near the cursor.",
		Default = true,
		Callback = function(enabled)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetFadeoutHover(enabled)
			end
		end,
	})
	playerEsp:AddSlider("YSL_PlayerESPTextSize", {
		Text = "Text size",
		Default = 12,
		Min = 6,
		Max = 60,
		Rounding = 0,
		Suffix = " px",
		Callback = function(value)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetTextSize(value)
			end
		end,
	})
	playerEsp:AddSlider("YSL_PlayerESPFadeDistance", {
		Text = "Fadeout distance",
		Default = 5000,
		Min = 100,
		Max = 50000,
		Rounding = 0,
		Suffix = " studs",
		Callback = function(value)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetFadeoutDistance(value)
			end
		end,
	})
	playerEsp:AddSlider("YSL_PlayerESPMaxDistance", {
		Text = "Max player distance",
		Default = 20000,
		Min = 100,
		Max = 50000,
		Rounding = 0,
		Suffix = " studs",
		Callback = function(value)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetMaxDistance(value)
			end
		end,
	})
	local tags = playerEsp:AddDropdown("YSL_PlayerESPTags", {
		Text = "ESP tags",
		Tooltip = "Choose which player details to include in name tags.",
		Values = {
			"Roblox Display Name",
			"Roblox Player Name",
			"Health %",
			"HP/Max",
			"Ping",
			"Distance",
			"Agility",
		},
		Multi = true,
		Default = {},
	})
	tags:SetValue({
		["Roblox Display Name"] = true,
		["Health %"] = true,
		["HP/Max"] = true,
		Ping = true,
		Distance = true,
	})
	if not context.ShowcaseOnly then
		tags.Callback = function(value)
			visuals.PlayerESP:SetTags(value)
		end
	end
	local playerEspGlobal = playerTab:AddRightGroupbox("Player ESP - Global")
	playerEspGlobal:AddDropdown("YSL_PlayerESPDistanceFormat", {
		Text = "Distance format",
		Values = { "meters & km", "studs" },
		Default = "meters & km",
		Callback = function(value)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetDistanceInStuds(value == "studs")
			end
		end,
	})
	playerEspGlobal:AddSlider("YSL_PlayerESPUpdateRate", {
		Text = "Label update rate",
		Default = 15,
		Min = 1,
		Max = 60,
		Rounding = 0,
		Suffix = " fps",
		Callback = function(value)
			if not context.ShowcaseOnly then
				visuals.PlayerESP:SetUpdateRate(value)
			end
		end,
	})
	end
	local targetHUDGroup = playerTab:AddRightGroupbox("Target HUD")
	if context.ShowcaseOnly then
		targetHUDGroup:AddLabel("Showcase placeholder controls.", true)
		targetHUDGroup:AddToggle("Demo_TargetHUD", {
			Text = "Enable target HUD",
			Default = false,
		})
		targetHUDGroup:AddToggle("Demo_TargetHUDHealth", {
			Text = "Show health",
			Default = true,
		})
	else
		setupTargetHUD(library, targetHUDGroup)
	end
	local arrayListGroup = settingsTab:AddRightGroupbox("Array List")
	arrayListGroup:AddToggle("YSL_ArrayListEnabled", {
		Text = "Show enabled features",
		Default = false,
		ArrayList = false,
		Callback = function(enabled)
			arrayList:SetVisible(enabled)
		end,
	})
	arrayListGroup:AddToggle("YSL_ArrayListBackground", {
		Text = "Word backgrounds",
		Tooltip = "Shows a compact dark background behind each enabled feature name.",
		Default = true,
		ArrayList = false,
		Callback = function(enabled)
			arrayList:SetBackgroundEnabled(enabled)
		end,
	})
	arrayListGroup:AddSlider("YSL_ArrayListTextSize", {
		Text = "Text size",
		Default = 14,
		Min = 10,
		Max = 24,
		Rounding = 0,
		Callback = function(value)
			arrayList:SetTextSize(value)
		end,
	})

	local controller = {}
	function controller:SetGradient(enabled, duration)
		arrayList:SetGradient(enabled, duration)
		if visuals then
			visuals:SetGradient(enabled, duration)
		end
	end
	library.VisualsController = controller
	controller:SetGradient(
		library.WindowOutlineGradientEnabled ~= false,
		library.WindowOutlineGradientDuration or 5
	)
	context.VisualsControllers = {
		Ambience = ambience,
		Visuals = visuals,
		ArrayList = arrayList,
	}
end

return {
	Setup = setupVisuals,
}
	end,
